<script setup lang="ts">
import { onMounted, ref } from 'vue'

interface TriangleSliderProps {
  max: number
  min: number
  value: number
}

// Define the initial thumb position and the thumb reference
interface Emits {
  (e: 'update:value', value: number): void
}

const props = defineProps<TriangleSliderProps>()
const emit = defineEmits<Emits>()

const thumbPosition = ref<number>(0) // Initial position of the slider thumb
const thumbRef = ref()
// Additional state to track the start position of the thumb and the pointer
const startPosition = ref<number>(0)
const startPointerPosition = ref<number>(0)
const isDragging = ref<boolean>(false)

const sliderHeight = 200
const thumbHeight = 32

onMounted(() => {
  // Set the initial thumb position based on the value
  thumbPosition.value = valueToPosition(props.value)
})

function valueToPosition(value) {
  const max = props.max
  const min = props.min
  const range = max - min
  const position = value - min
  const percentage = (position / range) * 100
  return ((sliderHeight - thumbHeight) * percentage) / 100
}

function startDrag(event) {
  // event.preventDefault() // Prevent default pointer down behavior
  isDragging.value = true
  // Record the initial pointer position and the current thumb position
  startPointerPosition.value = event.clientY
  startPosition.value = thumbPosition.value
  // Add event listeners to handle dragging and stopping
  window.addEventListener('pointermove', updatePosition)
  window.addEventListener('pointerup', stopDrag)
}

function updatePosition(event) {
  if (!isDragging.value) {
    return
  }
  const movementY = startPointerPosition.value - event.clientY
  let newPos = startPosition.value + movementY
  // Define the slider and thumb bounds
  const maxPosition = sliderHeight - thumbHeight // Maximum position value
  const minPosition = 0 // Minimum position value

  // Constrain newPosition within the slider's bounds
  newPos = Math.max(minPosition, Math.min(newPos, maxPosition))
  // Convert the position to a value
  emit('update:value', positionToValue(newPos))
  thumbPosition.value = newPos
}

function stopDrag() {
  // Stop dragging logic
  console.debug(event)
  isDragging.value = false
  window.removeEventListener('pointermove', updatePosition)
  window.removeEventListener('pointerup', stopDrag)
}

function positionToValue(value) {
  const max = props.max
  const min = props.min
  const range = max - min
  const position = value
  const percentage = (position / (sliderHeight - thumbHeight)) * 100
  const newValue = (percentage * range) / 100 + min
  return Math.round(newValue)
}
</script>

<template>
  <div class="triangle-slider" @pointerdown="startDrag">
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width="24"
      height="200"
      viewBox="0 0 24 200"
      fill="white"
    >
      <path
        d="M0.539453 11.9879C0.245527 5.45615 5.46169 0 12 0C18.5383 0 23.7545 5.45617 23.4605 11.9879L15.1349 197.003C15.0594 198.68 13.6782 200 12 200C10.3218 200 8.94058 198.68 8.86514 197.003L0.539453 11.9879Z"
        fill="white"
        fill-opacity="0.48"
        style="fill: white; fill-opacity: 0.48"
      />
    </svg>
    <div
      id="slider-thumb"
      ref="thumbRef"
      class="thumb"
      :style="{
        bottom: `${thumbPosition}px`,
        left: `12px`,
      }"
    />
  </div>
</template>

<style scoped>
.triangle-slider {
  position: relative;
