<script setup lang="ts">
import { IonButton, useIonRouter } from '@ionic/vue'
import { storeToRefs } from 'pinia'
import TextBubble from '@/components/TextBubble.vue'
import LeftArrowIcon from '@/components/svg/LeftArrowIcon.vue'
import CloseIcon from '@/components/svg/CloseIcon.vue'
import { useCreateUniverseStore } from '@/store/createUniverseStore'
import { CREATE_SEKAI_STEPS } from '@/constant/texts'
import CommonButton from '@/components/CommonButton.vue'
import { useToastStore } from '@/store/toast'

interface Emits {
  (e: 'onResetSekai'): void
}
defineEmits<Emits>()

const router = useIonRouter()
const createSekaiStore = useCreateUniverseStore()
const toastStore = useToastStore()
const { createStep, canPublish, showPublishGuide } = storeToRefs(createSekaiStore)

function routeBack() {
  if (router.canGoBack()) {
    router.back()
  }
  else {
    router.push('/')
  }
}
</script>

<template>
  <div
    id="page-header-wrapper"
    class="flex-shrink-0 w-full pt-unsafe-area pb-3 flex flex-col gap-4 absolute top-0 left-0 page-header z-200 bg-bg"
  >
    <div class="relative pt-1.5 flex justify-between items-center pl-1 pr-4">
      <ion-button
        v-if="createStep === 0 || createStep === 4" size="small" fill="clear" @click="
          () => {
            if (createStep === 0) {
              routeBack()
            }
            else {
              createSekaiStore.prevStep()
            }
          }
        "
      >
        <left-arrow-icon v-if="createStep === 4" />
        <close-icon v-else />
      </ion-button>
      <div v-else class="w-12 h-4" />

      <div class="flex flex-col items-center">
        <div class="relative text-5 fw-700 leading-7 text-on-bg-1 mb-1">
          {{ CREATE_SEKAI_STEPS[createStep] }}
        </div>
        <div class="flex gap-0.5">
          <div
            v-for="item in [0, 1, 2, 3, 4]" :key="item" class="step"
            :style="{ background: item !== createStep ? 'rgba(235, 235, 247, 0.30)' : 'rgba(255, 255, 255, 1)' }"
          />
        </div>
      </div>

      <common-button
        v-if="createStep === 4" text="Publish" :bg-color="canPublish ? 'bg-#00F4FF' : 'bg-#818181'"
        :text-color="canPublish ? 'text-#333' : 'text-f0f0f0'" @click="() => {
          if (!canPublish) {
            toastStore.setToast('Generating the first scenario story...')
            return
          }
          createSekaiStore.nextStep(() => {
            $emit('onResetSekai')
            routeBack()
          })
        }"
      />
      <div v-else class="w-12 h-4" />
      <div
        v-if="showPublishGuide && createStep === 4"
        class="absolute top-13 right-8"
        @pointerdown="() => createSekaiStore.setShowPublishGuide(false)"
      >
        <text-bubble
          text="Tap here to publish sekai"
          position="top-right"
        />
      </div>
    </div>
  </div>
</template>

<style scoped>
.step {
  width: 32px;
  height: 2px;
}
</style>
