<script setup lang="ts">
import { ref } from 'vue'
import { IonTextarea } from '@ionic/vue'
import { useCreateUniverseStore } from '@/store/createUniverseStore'
import LoadingComponent from '@/components/LoadingComponent.vue'
import { universeService } from '@/services/universe'
import IdeaIcon from '@/components/svg/IdeaIcon.vue'

const createUniverseStore = useCreateUniverseStore()
const loading = ref(false)

async function onGoNext() {
  try {
    loading.value = true
    await createUniverseStore.generateEventSuggestion()
    createUniverseStore.nextStep()
  }
  catch (err) {
    console.error(err)
  }
  finally {
    loading.value = false
  }
}

async function getPrepareWhatIf() {
  const res = await universeService.getPrepareWhatif()
  console.log(res)
  if (res) {
    createUniverseStore.whatIf = res.data
  }
}
</script>

<template>
  <loading-component v-if="loading" text="Generating Scenario Suggestions..." />
  <div v-else>
    <div>
      <div class="card">
        <div class="title">
          Where does your story start?
        </div>
        <div class="desc">
          This could be a parody, an old movie concept, or a meme about your
          favorite characters.
        </div>
        <ion-textarea
          id="user_char_textarea" v-model="createUniverseStore.whatIf" class="mt-2 text-area"
          placeholder="Examples:
Hutao became an overprotective and strict Asian mom who is blaming his son Aether in front of his teacher Ganyu for doing poorly in school." autocomplete="on" autocorrect="on" autocapitalize="on" :rows="5"
          :auto-grow="true" :error-text="$t('createUniversePage.isRequired')" :maxlength="1200"
        />
        <div class="flex justify-between mt-2 ">
          <div class="word-limit">
            {{ createUniverseStore.whatIf.length }} / 1200
          </div>
          <div class="flex justify-center items-center gap-2 py-2 idea-btn" @click="getPrepareWhatIf">
            <idea-icon />
            <span>Ideas</span>
          </div>
          <div style="width: 100px;" />
        </div>
      </div>
    </div>
    <div class="fixed bottom-0 left-0 w-full pb-unsafe-area">
      <div class="px-4 pb-2">
        <button
          :disabled="createUniverseStore.whatIf.length === 0" class="btn-primary"
          :style="{ backgroundColor: createUniverseStore.whatIf.length === 0 ? '#3D3D3D' : '' }" @click="
            () => {
              onGoNext();
            }
          "
        >
          {{ $t("createUniversePage.generate") }}
        </button>
      </div>
    </div>
  </div>
</template>

