<script setup lang="ts">
import { ref } from 'vue'
import CreateSekaiFooter from './CreateSekaiFooter.vue'
import type { GeneratedEventModel } from '@/types/event'
import LoadingLottie from '@/components/LoadingLottie.vue'
import RefreshIcon from '@/components/svg/RefreshIcon.vue'
import { useCreateUniverseStore } from '@/store/createUniverseStore'
import CheckIconCircleEmpty from '@/components/svg/CheckIconCircleEmpty.vue'
import CheckedIconCircleFill from '@/components/svg/CheckedIconCircleFill.vue'
import EditIcon from '@/components/svg/EditIcon.vue'

const createUniverseStore = useCreateUniverseStore()
const loading = ref(false)

async function regenerateEvents() {
  try {
    loading.value = true
    createUniverseStore.selectedEventSuggestion = -1
    await createUniverseStore.generateEventSuggestion(true)
  }
  catch (e) {
    console.error(e)
  }
  finally {
    loading.value = false
  }
}

function handleEventSelect(event: GeneratedEventModel, index: number) {
  console.log(event)
  createUniverseStore.selectedEventSuggestion = index
}

function handleGoNext() {
  const event
    = createUniverseStore.eventsSuggestions?.[
      createUniverseStore.selectedEventSuggestion
    ]
  if (event) {
    createUniverseStore.basicSettingBackground = event.background
    createUniverseStore.basicSettingScenario = `${event.eventDescription}This scenario includes characters: ${event.charNames.join(', ')}`
  }
  createUniverseStore.nextStep()
}
</script>

<template>
  <div class="relative mt-4 px-4 pb-unsafe-area">
    <div class="h-full flex justify-center flex-col align-center mb-unsafe-area pb-12">
      <div v-if="loading" class="h-1/3">
        <loading-lottie />
      </div>
      <div v-else class="h-full flex flex-col flex-grow">
        <div class="flex flex-col flex-grow overflow-y-auto gap-4">
          <div
            v-for="(event, index) in createUniverseStore.eventsSuggestions"
            :key="index"
            class="flex flex-col p-3 rd-4 border-solid border-width-1 border-#BDBDBD bg-#594500 event-card"
            :style="{
              border:
                createUniverseStore.selectedEventSuggestion === index
                  ? '2px solid #FFF'
                  : '',
            }"
            @click="() => handleEventSelect(event, index)"
          >
            <div class="flex gap-2">
              <checked-icon-circle-fill
                v-if="createUniverseStore.selectedEventSuggestion === index"
                style="width: 24px; height: 24px"
              />
              <check-icon-circle-empty
                v-else
                style="width: 24px; height: 24px"
              />
              <p class="flex-1 text-4 fw-400 line-height-normal">
                {{ event.eventDescription }} <br>
                Characters: {{ event.charNames.join(", ") }}
              </p>
            </div>
          </div>
        </div>
      </div>
      <div class="flex items-center gap-4 mt-4">
        <button
          v-if="!loading"
          class="btn-secondary min-h-12"
          @click="regenerateEvents"
        >
          <refresh-icon style="width: 24px" />
          Regenerate
        </button>
        <button
          v-if="!loading"
          class="btn-secondary min-h-12"
          @click="handleGoNext"
        >
          <edit-icon style="width: 24px" />
          Write yourself
        </button>
      </div>
      <div class="fixed bottom-unsafe-area left-0 w-full">
        <create-sekai-footer
          :show-go-back="true"
          :disable-go-next="createUniverseStore.selectedEventSuggestion === -1"
          @on-next-click="handleGoNext()"
        />
      </div>
    </div>
    <div class="h-4" />
  </div>
</template>

<style scoped>
.event-card {
  background: rgba(255, 255, 255, 0.24);
  box-sizing: border-box;
}
</style>
