<script setup lang="ts">
import { IonTextarea } from '@ionic/vue'
import { nextTick, onMounted, ref, watch } from 'vue'
import VueDraggableResizable from 'vue-draggable-resizable'

interface Props {
  fontSize: number
  editting: boolean
}

interface Emits {
  (e: 'dragging', dragging: boolean): void
  (e: 'updatePos', x: number, y: number): void
  (e: 'updateText', text: string): void
}
const props = defineProps<Props>()
const emit = defineEmits<Emits>()

const x = ref(0)
const y = ref(0)
const width = ref(window.innerWidth - 48)
const height = ref(props.fontSize * 1.2)
const text = ref('')
const maxWidth = window.innerWidth
const textAreaRef = ref()

onMounted(() => {
  // center the draggable-resizable component
  x.value = window.innerWidth / 2 - width.value / 2
  y.value = window.innerHeight / 2
})

// watch the textAreaRef has been mounted
watch(
  () => textAreaRef.value,
  () => {
    // When the first time mounted, set focus
    setTimeout(() => {
      if (!textAreaRef.value) {
        return
      }
      textAreaRef.value?.$el.setFocus()
    }, 10)
  },
)

watch(
  () => text.value,
  (val) => {
    emit('updateText', val)
    const lines = val.split('\n')
    // set the width
    width.value = Math.min(
      Math.max(...lines.map(line => line.length)) * props.fontSize * 0.6,
      window.innerWidth,
    )
    height.value = props.fontSize * 1.2 * lines.length
    text.value = lines.join('\n')
  },
)

watch(
  () => props.editting,
  (val) => {
    // focus on the textarea when editting
    console.debug('editting', val)
    if (val) {
      nextTick(() => {
        if (!textAreaRef.value) {
          return
        }
        textAreaRef.value?.$el.setFocus()
      })
    }
  },
)

function onDrag(newX, newY) {
  emit('dragging', true)
  x.value = newX
  y.value = newY
  emit('updatePos', x.value, y.value)
}

const inputFocus = ref(false)

function onFocus() {
  inputFocus.value = true
}

function onBlur() {
  inputFocus.value = false
}
</script>

<template>
  <vue-draggable-resizable
    v-if="!editting"
    :x="x"
    :y="y"
    :w="width"
    :h="height"
    :resizable="false"
    :draggable="!editting"
    class="my-resizable-component"
    :max-width="maxWidth"
    @dragging="
      (x, y) => {
        onDrag(x, y);
      }
    "
    @drag-stop="
      () => {
        console.debug('dragstop');
        emit('dragging', false);
      }
    "
  >
    <div class="component-content" :style="{ fontSize: `${fontSize}px` }">
      {{ text }}
    </div>
  </vue-draggable-resizable>
  <ion-textarea
    v-else
    ref="textAreaRef"
    v-model="text"
    class="bg-transparent border-none text-white absolute top-1/2 left-4 -translate-y-1/2 text-left"
    :style="{ fontSize: `${fontSize}px`, width: 'calc(100% - 64px)' }"
    autocomplete="on"
    autocorrect="on"
    autocapitalize="on"
    :rows="3"
    :auto-grow="true"
    :maxlength="1200"
    placeholder="Enter here"
    @ion-focus="onFocus"
    @ion-blur="onBlur"
  />
</template>

<style scoped>
.my-resizable-component {
  border: none;
  color: #fff;
}
</style>
