<script setup lang="ts">
import PlayIcon from './svg/PlayIcon.vue'
import PauseIcon from './svg/PauseIcon.vue'
import SignedImg from './SignedImg.vue'
import type { IBGMItem } from '@/types/audio'

const props = defineProps<Props>()
const emits = defineEmits(['clickPlay'])

interface Props {
  item: IBGMItem
  playing?: boolean
}
const durationText = `${`00${Math.floor(props.item.duration / 60)}`.slice(-2)}:${`00${(props.item.duration % 60)}`.slice(-2)}`

async function play() {
  emits('clickPlay', props.item.id)
}
</script>

<template>
  <div class="flex gap-2 overflow-hidden" @click="play">
    <div class="cover-container">
      <signed-img class="cover" :src="props.item.coverUrl" />
      <play-icon v-if="props.playing === false" class="play-btn" />
      <pause-icon v-else class="play-btn" />
    </div>
    <div class="flex flex-1 flex-col justify-between overflow-hidden">
      <div class="title truncate">
        {{ props.item.name }}
      </div>
      <div class="duration">
        {{ durationText }}
      </div>
    </div>
  </div>
</template>

