<script setup lang="ts">
import { onMounted, onUnmounted, ref, watch } from 'vue'
import ResizeDragTitle from '@/components/ResizeDragTitle.vue'
import TriangleSlider from '@/components/TriangleSlider.vue'
import DeleteIcon from '@/components/svg/DeleteIcon.vue'
import { useTextTitleStore } from '@/store/textTitleStore'

interface Props {
  show: boolean
}

interface Emits {
  (e: 'onEditTitle', edit: boolean): void
  (e: 'onDeleteTitle'): void
}

defineProps<Props>()
const emit = defineEmits<Emits>()

const textTitleStore = useTextTitleStore()

// UI Refs
const titleRef = ref()

const fontSize = ref(36)
const textPosition = ref({ x: 0, y: 0 })
// watch the fontSize to update the title width and height
// calculate the title width and height from font size
watch(
  () => fontSize.value,
  (val) => {
    textTitleStore.updateTitleSize(val * 10, val * 2)
  },
)

// watch the text position to update the title position
watch(
  () => textPosition.value,
  (val) => {
    textTitleStore.updateTitlePosition(val.x, val.y)
  },
  { deep: true },
)

const editMode = ref(false)
// watch the editMode to update onEditTitle
watch(
  () => editMode.value,
  (val) => {
    emit('onEditTitle', val)
  },
)
const isDragging = ref(false)
const text = ref('')
// watch text to update the title text
watch(
  () => text.value,
  (val) => {
    textTitleStore.updateTitleText(val)
  },
)

/**
 * check for the collision between the title and the delete area
 */
function onDrag(dragging) {
  isDragging.value = dragging
  const deleteArea = document.getElementById('delete-area')
  if (!deleteArea) {
    return
  }
  const title = titleRef.value.$el
  const titleRect = title.getBoundingClientRect()
  const deleteAreaRect = deleteArea.getBoundingClientRect()
  if (isColliding(titleRect, deleteAreaRect)) {
    if (dragging) {
      deleteArea.style.opacity = '0.8'
    }
    else {
      emit('onDeleteTitle')
    }
  }
  else {
    deleteArea.style.opacity = '1'
  }
}

/**
 * check for the collision between two rectangles
 */
function isColliding(rect1, rect2) {
  return !(
    rect1.right < rect2.left
    || rect1.left > rect2.right
    || rect1.bottom < rect2.top
    || rect1.top > rect2.bottom
  )
}

/**
 * show the edit button when the title is clicked
 */
function onTitleClick(e) {
  e.stopPropagation()

  if (editMode.value) {
    return
  }
  editMode.value = true
}

// set to edit mode when mounted
onMounted(() => {
  console.debug('Mounted CreatePovTitle')
  editMode.value = true
})

onUnmounted(() => {
  console.debug('Unmounted CreatePovTitle')
  emit('onEditTitle', false)
})
</script>

<template>
  <div
    v-show="isDragging"
    id="delete-area"
    class="absolute top-12 left-1/2 -translate-x-1/2 bg-#373737 flex flex-col gap-1 items-center p-2 text-#bdbdbd rd-2"
    @click="
      (e) => {
        e.stopPropagation();
        editMode = !editMode;
      }
    "
  >
    <delete-icon />
    <p class="color-#fff">
      Drag here to delete
    </p>
  </div>
  <resize-drag-title
    v-show="show"
    ref="titleRef"
    :font-size="fontSize"
    :editting="editMode"
    @dragging="onDrag"
    @update-pos="
      (x, y) => {
        textPosition.x = x;
        textPosition.y = y;
      }
    "
    @update-text="
      (value) => {
        text = value;
      }
    "
    @click="onTitleClick"
  />
  <div
    v-if="editMode"
    :class="`${editMode && 'mask'} relative h-full pt-unsafe-area`"
  >
    <div
      class="absolute pt-unsafe-area top-4 right-4 color-#fff text-4 leading-normal"
      @click="
        () => {
          editMode = false;
          if (text.length === 0) {
            emit('onDeleteTitle');
          }
        }
      "
    >
      Done
    </div>
    <div class="absolute top-1/2 -translate-y-1/2 right-4">
      <triangle-slider
        :max="64"
        :min="8"
        :value="fontSize"
        @update:value="
          (value) => {
            console.debug(value);
            fontSize = value;
          }
        "
      />
    </div>
  </div>
</template>

<style scoped>
.mask {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.4);
}
</style>
